package hard;public class ThreeSumClosest{public static int threeSumClosest(int[]n,int t){java.util.Arrays.sort(n);int c=n[0]+n[1]+n[2];for(int i=0;i<n.length-2;i++){int l=i+1,r=n.length-1;while(l<r){int s=n[i]+n[l]+n[r];if(s==t)return s;if(Math.abs(s-t)<Math.abs(c-t))c=s;if(s<t)l++;else r--;}}return c;}public static void main(String[]args){System.out.println("Closest: "+threeSumClosest(new int[]{-1,2,1,-4},1));}}
